from dataclasses import dataclass


@dataclass(frozen=True)
class Range:
    name: str   # a named loop counter
    bound: int  # and its bound

@dataclass(frozen=True)
class Const:
    value: int

@dataclass(frozen=True)
class Add:
    a: "Node"
    b: "Node"

@dataclass(frozen=True)
class Store:
    offset: "Node"
    value: "Node"

@dataclass(frozen=True)
class End:
    effect: "Node"
    range: "Node"  # closes this range

Node = Range | Const | Add | Store | End


def opens(n: Node) -> list[str]:
    """The names of the ranges n depends on that no End has closed, sorted, no duplicates."""
